css:
[data-workspace-area="conversation"],.messages-timeline-scroll,[data-chat-header]{background:transparent!important}
@keyframes fj-drift{0%{background-position:0% 0%,100% 0%,0 0}100%{background-position:100% 0%,0% 0%,0 0}}
[data-chat-canvas]{background-image:radial-gradient(ellipse 45% 34% at 50% 0%,rgba(92,200,232,.18),transparent 70%),radial-gradient(ellipse 40% 30% at 50% 0%,rgba(110,230,170,.13),transparent 70%),linear-gradient(180deg,rgba(14,22,33,0),rgba(6,12,20,.6))!important;background-size:170% 100%,170% 100%,100% 100%!important;background-repeat:no-repeat!important;animation:fj-drift 28s ease-in-out infinite alternate}
@media (prefers-reduced-motion:reduce){[data-chat-canvas]{animation:none!important}}
.chat-markdown a{color:#7fd8f2!important}
::selection{background:rgba(92,200,232,.3)}
